-- hrm.rpt_att_muster: The daily muster (FR-HRM-ATT-19, RPT-05): the current result of every employee and day with the unit, branch and location of that day. No pay or salary column (FR-HRM-GHR-06). Read-only; data scope is applied by the report service.
create or replace view hrm.rpt_att_muster with (security_invoker = true) as
select d.id as day_id, d.company_id, d.employment_id, e.employee_no, p.first_name, p.last_name,
       a.org_unit_id, a.branch_id, a.location_id,
       d.work_date, d.shift_id, d.day_type, d.result, d.first_in, d.last_out,
       d.worked_minutes, d.late_minutes, d.early_minutes, d.overtime_minutes
from hrm.attendance_days d
join hrm.employments e on e.id = d.employment_id
join hrm.persons p on p.id = e.person_id
left join hrm.employment_assignments a
       on a.employment_id = d.employment_id and a.valid_from <= d.work_date and (a.valid_to is null or a.valid_to > d.work_date)
where d.superseded_at is null;
grant select on hrm.rpt_att_muster to app_rw, app_ro, backup;

-- hrm.rpt_att_muster_monthly: The monthly muster: per employee and month, the days by result and the minutes (FR-HRM-ATT-19, RPT-05). No pay or salary column.
create or replace view hrm.rpt_att_muster_monthly with (security_invoker = true) as
select m.company_id, m.employment_id, m.employee_no, m.first_name, m.last_name,
       (array_agg(m.org_unit_id order by m.work_date desc))[1] as org_unit_id,
       (array_agg(m.branch_id order by m.work_date desc))[1] as branch_id,
       (array_agg(m.location_id order by m.work_date desc))[1] as location_id,
       date_trunc('month', m.work_date)::date as month,
       count(*) filter (where m.result = 'present') as present_days,
       count(*) filter (where m.result = 'absent') as absent_days,
       count(*) filter (where m.result = 'late') as late_days,
       count(*) filter (where m.result = 'half_day') as half_days,
       count(*) filter (where m.result = 'on_leave') as leave_days,
       count(*) filter (where m.result = 'holiday') as holiday_days,
       count(*) filter (where m.result = 'weekly_off') as weekly_off_days,
       count(*) filter (where m.result = 'on_duty') as duty_days,
       count(*) filter (where m.result = 'incomplete') as incomplete_days,
       sum(m.worked_minutes)::bigint as worked_minutes,
       sum(m.late_minutes)::bigint as late_minutes,
       sum(m.early_minutes)::bigint as early_minutes,
       sum(m.overtime_minutes)::bigint as overtime_minutes
from hrm.rpt_att_muster m
group by m.company_id, m.employment_id, m.employee_no, m.first_name, m.last_name, date_trunc('month', m.work_date)::date;
grant select on hrm.rpt_att_muster_monthly to app_rw, app_ro, backup;

-- hrm.rpt_att_absenteeism: Absenteeism per employee and month: the days that were to be worked, the days absent and half days, and the absence rate (FR-HRM-ATT-19). No pay or salary column.
create or replace view hrm.rpt_att_absenteeism with (security_invoker = true) as
select m.company_id, m.employment_id, m.employee_no, m.first_name, m.last_name,
       (array_agg(m.org_unit_id order by m.work_date desc))[1] as org_unit_id,
       (array_agg(m.branch_id order by m.work_date desc))[1] as branch_id,
       (array_agg(m.location_id order by m.work_date desc))[1] as location_id,
       date_trunc('month', m.work_date)::date as month,
       count(*) filter (where m.day_type = 'working') as scheduled_days,
       count(*) filter (where m.result = 'absent') as absent_days,
       count(*) filter (where m.result = 'half_day') as half_days,
       count(*) filter (where m.result = 'late') as late_days,
       round(100.0 * count(*) filter (where m.result = 'absent') / nullif(count(*) filter (where m.day_type = 'working'), 0), 2) as absence_percent
from hrm.rpt_att_muster m
group by m.company_id, m.employment_id, m.employee_no, m.first_name, m.last_name, date_trunc('month', m.work_date)::date;
grant select on hrm.rpt_att_absenteeism to app_rw, app_ro, backup;

-- hrm.rpt_att_late_early: Late and early days: the days with minutes late or early (FR-HRM-ATT-19). Penalties and waivers are S1.29b's. No pay or salary column.
create or replace view hrm.rpt_att_late_early with (security_invoker = true) as
select m.day_id, m.company_id, m.employment_id, m.employee_no, m.first_name, m.last_name, m.org_unit_id, m.branch_id, m.location_id,
       m.work_date, m.shift_id, m.result, m.first_in, m.last_out, m.late_minutes, m.early_minutes
from hrm.rpt_att_muster m
where m.late_minutes > 0 or m.early_minutes > 0;
grant select on hrm.rpt_att_late_early to app_rw, app_ro, backup;

-- hrm.rpt_att_punch_log: The punch log: every punch with its source and device (FR-HRM-ATT-19). The address a punch came from is not shown. No pay or salary column.
create or replace view hrm.rpt_att_punch_log with (security_invoker = true) as
select v.id as event_id, v.company_id, v.employment_id, e.employee_no, p.first_name, p.last_name,
       a.org_unit_id, a.branch_id, a.location_id,
       v.event_date, v.event_at, v.direction, v.source, v.device_id, dv.serial_no as device_serial_no, v.received_at, v.is_duplicate,
       v.supersedes_event_id
from hrm.attendance_events v
join hrm.employments e on e.id = v.employment_id
join hrm.persons p on p.id = e.person_id
left join hrm.attendance_devices dv on dv.id = v.device_id
left join hrm.employment_assignments a
       on a.employment_id = v.employment_id and a.valid_from <= v.event_date and (a.valid_to is null or a.valid_to > v.event_date);
grant select on hrm.rpt_att_punch_log to app_rw, app_ro, backup;

-- hrm.rpt_att_device_sync: Device sync: each device with its state, last contact, last sync, last error and the device punches still waiting to be mapped (FR-HRM-ATT-19). No secret and no pay or salary column.
create or replace view hrm.rpt_att_device_sync with (security_invoker = true) as
select d.id as device_id, d.company_id, d.location_id, d.serial_no, d.model, d.status, d.last_seen_at, d.last_sync_at, d.last_error, d.sync_cursor_at,
       (select count(*) from hrm.unmapped_punches u where u.device_id = d.id and u.status = 'open') as open_unmapped_punches
from hrm.attendance_devices d
where d.deleted_at is null;
grant select on hrm.rpt_att_device_sync to app_rw, app_ro, backup;

-- hrm.rpt_att_exceptions: Attendance exceptions with the person and place, for the ageing report (FR-HRM-ATT-19); the age is worked out at read time from the company's date. No pay or salary column.
create or replace view hrm.rpt_att_exceptions with (security_invoker = true) as
select x.id as exception_id, x.company_id, x.employment_id, e.employee_no, p.first_name, p.last_name,
       a.org_unit_id, a.branch_id, a.location_id,
       x.work_date, x.kind, x.status, x.attendance_day_id, x.created_at, x.updated_at
from hrm.attendance_exceptions x
join hrm.employments e on e.id = x.employment_id
join hrm.persons p on p.id = e.person_id
left join hrm.employment_assignments a
       on a.employment_id = x.employment_id and a.valid_from <= x.work_date and (a.valid_to is null or a.valid_to > x.work_date);
grant select on hrm.rpt_att_exceptions to app_rw, app_ro, backup;
